#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: research accounts for apps/research (ticket 09 of
# .scratch/audience-research). Secrets go to credentials.json at the root of
# the main checkout (git-ignored), never to the screen.
# ──────────────────────────────────────────────────────────────────────────

# The main checkout's root, found from this script's own location (works from
# any directory, and from a worktree). Fails loudly instead of guessing.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
COMMON_DIR="$(git -C "$SCRIPT_DIR" rev-parse --path-format=absolute --git-common-dir)" \
  || { echo "Can't find the repo from $SCRIPT_DIR" >&2; exit 1; }
REPO_ROOT="$(cd "$COMMON_DIR/.." && pwd)"
CREDS="$REPO_ROOT/credentials.json"
# node on Windows needs a Windows path (E:/...), not Git Bash's /e/...
command -v cygpath >/dev/null 2>&1 && CREDS="$(cygpath -m "$CREDS")"
[[ -f "$CREDS" ]] || { echo "Expected the existing credentials.json at $CREDS" >&2; exit 1; }
WRITTEN_CREDS=()

# write_cred SECTION KEY VALUE: upsert credentials.json[SECTION][KEY] (or
# credentials.json[KEY] when SECTION is empty). Values travel by environment,
# never argv, so they don't show in the process list.
write_cred() {
  WC_SECTION="$1" WC_KEY="$2" WC_VALUE="$3" WC_FILE="$CREDS" node -e '
    const fs = require("fs");
    const f = process.env.WC_FILE;
    const c = fs.existsSync(f) ? JSON.parse(fs.readFileSync(f, "utf8")) : {};
    const s = process.env.WC_SECTION, k = process.env.WC_KEY, v = process.env.WC_VALUE;
    if (s) { c[s] = c[s] || {}; c[s][k] = v; } else { c[k] = v; }
    fs.writeFileSync(f, JSON.stringify(c, null, 2) + "\n", { mode: 0o600 });
  '
  WRITTEN_CREDS+=("${1:+$1.}$2")
}

run_wizard() {

TOTAL_STAGES=5

banner "LlamaPoker research accounts"

stage "A research-only Chrome profile"
say "Every research login lives in its own Chrome profile, so a blocked research"
say "account can never touch LlamaPoker's or your personal accounts."
step "In Chrome, click your profile picture (top right) → Add → Continue without an account."
step "Name it exactly: research   (pick a colour you'll recognise)."
step "In that new window, sign in to nothing personal. No Google account sync."
warn "From now on, every research login below happens in THIS profile only."
pause

stage "A research-only Reddit account"
say "In the research profile window:"
open_url "https://www.reddit.com/register/"
step "Sign up with an email that is not the LlamaPoker one or your personal one"
step "(a new free mailbox is fine). Pick a neutral username, no brand name."
step "Verify the email if Reddit asks."
ask REDDIT_USERNAME "Reddit username (no u/):"
ask_secret REDDIT_PASSWORD "Reddit password:"
write_cred reddit_research username "$REDDIT_USERNAME"
write_cred reddit_research password "$REDDIT_PASSWORD"

stage "Reddit: a 'script' app for the API"
say "Still logged in as the research account, in the research profile:"
open_url "https://www.reddit.com/prefs/apps"
step "Scroll down → 'create another app…' (or 'are you a developer? create an app…')."
step "name: llamapoker-research   type: choose 'script'"
step "description: leave empty   redirect uri: http://localhost:8080"
step "Click 'create app'."
warn "If Reddit shows a form asking you to register or request API access instead,"
warn "fill it in (use: personal research on poker discussions, read-only), then"
warn "come back here once the app exists. Ctrl+C now is fine; re-running keeps nothing."
step "The client id is the short string under 'personal use script', below the app name."
ask REDDIT_CLIENT_ID "Client id:"
step "The secret is next to 'secret'."
ask_secret REDDIT_CLIENT_SECRET "Secret:"
write_cred reddit_research client_id "$REDDIT_CLIENT_ID"
write_cred reddit_research client_secret "$REDDIT_CLIENT_SECRET"
REDDIT_UA="windows:llamapoker-research:0.1 (by /u/$REDDIT_USERNAME)"
write_cred reddit_research user_agent "$REDDIT_UA"

stage "Check: Reddit gives us a token"
say "Asking Reddit for an access token with what you just saved…"
code=$(curl -s -o /dev/null -w '%{http_code}' -A "$REDDIT_UA" \
  -u "$REDDIT_CLIENT_ID:$REDDIT_CLIENT_SECRET" \
  --data-urlencode "grant_type=password" \
  --data-urlencode "username=$REDDIT_USERNAME" \
  --data-urlencode "password=$REDDIT_PASSWORD" \
  https://www.reddit.com/api/v1/access_token || echo "000")
if [[ "$code" == "200" ]]; then
  say "${GREEN}✓ Reddit answered 200: the API access works.${RESET}"
else
  warn "Reddit answered $code. Common causes: wrong secret, the app is not type"
  warn "'script', or 2-factor login is on for this account (turn it off for it)."
  SKIPPED+=("Reddit token check failed ($code); fix and re-run this wizard")
fi
pause

stage "Optional: a YouTube Data API key"
say "Not needed (we collect YouTube with yt-dlp). Only useful as a backup route."
if confirm "Create a YouTube API key now?"; then
  open_url "https://console.cloud.google.com/projectcreate"
  step "In the research profile: create a project named llamapoker-research."
  open_url "https://console.cloud.google.com/apis/library/youtube.googleapis.com"
  step "Select that project → Enable."
  open_url "https://console.cloud.google.com/apis/credentials"
  step "Create credentials → API key → copy it (optionally restrict it to YouTube Data API v3)."
  ask_secret YOUTUBE_API_KEY "API key:"
  write_cred "" youtube_api_key "$YOUTUBE_API_KEY"
else
  note "Skipped."
fi
pause

finish
(( ${#WRITTEN_CREDS[@]} )) && note "saved to $CREDS (git-ignored): ${WRITTEN_CREDS[*]}"
printf '\n'
}

run_wizard "$@"; exit
